import{_ as t,o as r,c as e,ag as s}from"./chunks/framework.D5hoimZQ.js";const q=JSON.parse('{"title":"科学日报 · 2026-10-12（AI 系统架构）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/science-daily-2026-10-12.md","filePath":"topics/ai-system-architecture/science-daily-2026-10-12.md"}'),n={name:"topics/ai-system-architecture/science-daily-2026-10-12.md"};function i(a,o,c,g,l,d){return r(),e("div",null,[...o[0]||(o[0]=[s('<h1 id="科学日报-·-2026-10-12-ai-系统架构" tabindex="-1">科学日报 · 2026-10-12（AI 系统架构） <a class="header-anchor" href="#科学日报-·-2026-10-12-ai-系统架构" aria-label="Permalink to &quot;科学日报 · 2026-10-12（AI 系统架构）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-12.md</code> — 第35期 ｜ AI 板块（arXiv cs.AI，10-08 批次）</p></blockquote><hr><h2 id="brickbench-让智能体去-拼乐高-考的是能不能真拼得起来-arxiv-2610-12452" tabindex="-1">BrickBench：让智能体去&quot;拼乐高&quot;，考的是能不能真拼得起来（arXiv:2610.12452） <a class="header-anchor" href="#brickbench-让智能体去-拼乐高-考的是能不能真拼得起来-arxiv-2610-12452" aria-label="Permalink to &quot;BrickBench：让智能体去&quot;拼乐高&quot;，考的是能不能真拼得起来（arXiv:2610.12452）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-12.md</code> ｜ arXiv: 2610.12452</p></blockquote><ul><li>设定：<strong>文本条件乐高设计</strong>——给定提示词，智能体从<strong>离散零件库</strong>选件，产出<strong>物理上真能拼起来</strong>的装配体（不是图片）。</li><li>难点：必须<strong>同时</strong>满足<strong>局部约束</strong>（连接、稳定性）与<strong>全局约束</strong>（语义、可搭建性）——是<strong>联合约束满足</strong>问题。</li><li>评测：三种规模/零件可用性设置下，从<strong>有效性、语义对齐、设计质量</strong>三维打分；提供 <strong>BrickAgent</strong> 环境供编码智能体构建/检查/验证。</li><li>结果：主流智能体<strong>大体满足可验证的物理与语义要求</strong>，但整体设计<strong>不及人类作品</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code>）：把&quot;智能体能力&quot;逼到一个<strong>可自动验证</strong>的物理域里——<strong>好处是&quot;对不对&quot;有硬判据</strong>（能不能拼起来），坏处（也是发现）是<strong>人类在&quot;设计品味&quot;上仍领先</strong>。与 <code>codex</code>/harness 主线同构：<strong>先分清&quot;可验证约束&quot;与&quot;不可验证偏好&quot;，再谈智能体到底强在哪。</strong></li></ul><hr><h2 id="预测-对齐泛化-看激活值远比看文字描述靠谱-arxiv-2610-12410" tabindex="-1">预测&quot;对齐泛化&quot;：看激活值远比看文字描述靠谱（arXiv:2610.12410） <a class="header-anchor" href="#预测-对齐泛化-看激活值远比看文字描述靠谱-arxiv-2610-12410" aria-label="Permalink to &quot;预测&quot;对齐泛化&quot;：看激活值远比看文字描述靠谱（arXiv:2610.12410）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-12.md</code> ｜ arXiv: 2610.12410</p></blockquote><ul><li>问题：模型被后训练去遵循&quot;对齐目标&quot;里的亲社会价值，但<strong>在少数价值上训练会以意想不到的方式改变它在大量未见情境中的行为</strong>。</li><li>任务（新立）：<strong>对齐泛化预测</strong>——预测对某个价值做微调会如何改变模型在<strong>留出价值</strong>上的行为。</li><li>规模：对现代对齐目标中的 <strong>66 个价值</strong>做大规模分析，并基准不同表示方法。</li><li>关键结果：基于**&quot;在上下文中应用价值时的模型激活&quot;<strong>的表示，与泛化矩阵相关系数达 <strong>0.45</strong>；基于</strong>价值文字描述**的基线仅 <strong>0.05</strong>。</li><li>下游：该表示可用于度量多价值目标内部的**&quot;价值相似度&quot;<strong>，与模型</strong>鲁棒性显著相关**；据此给出首个<strong>以实证泛化动力学为依据的 LLM 价值分类法</strong>，并给出&quot;<strong>模型无关价值空间</strong>&quot;的初步证据。</li><li>洞察（对本库 <code>ai-system-architecture</code> / <code>echo-gap-memory-reward-inflation.md</code>）：又一次&quot;<strong>描述 ≠ 实际</strong>&quot;——<strong>模型的文字自述（价值描述）几乎没预测力，真正的行为结构藏在激活里</strong>。这是 Echo Gap 原则的又一硬证据：<strong>任何&quot;以文字自评为依据&quot;的对齐/评估都必须用内部表征做反事实校验。</strong></li></ul><hr><h2 id="从内部连接看推理-小世界指数是-llm-推理能力的结构签名-arxiv-2610-12304" tabindex="-1">从内部连接看推理：小世界指数是 LLM 推理能力的结构签名（arXiv:2610.12304） <a class="header-anchor" href="#从内部连接看推理-小世界指数是-llm-推理能力的结构签名-arxiv-2610-12304" aria-label="Permalink to &quot;从内部连接看推理：小世界指数是 LLM 推理能力的结构签名（arXiv:2610.12304）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-12.md</code> ｜ arXiv: 2610.12304</p></blockquote><ul><li>灵感：神经科学发现<strong>更高智力对应更强的小世界组织</strong>。</li><li>方法：用<strong>注意力头激活相似度</strong>构建<strong>功能图</strong>，计算<strong>小世界指数（SWI）</strong>（兼顾<strong>局部聚集 + 全局短路径</strong>）。</li><li>结果：SWI 更高<strong>稳定地</strong>与更好的<strong>流体推理</strong>表现相关，且<strong>跨模型与训练检查点</strong>成立。</li><li>结构细节：对性能重要的头倾向<strong>在自身社区内占更大连接权重（高 core 分）</strong>、<strong>跨社区权重更集中（低 bridge 分）</strong>。</li><li>应用：据此提出 <strong>Small-World Allocation（SWA）</strong> 剪枝——按 core/bridge 分做层次化稀疏分配，在 <strong>6 个 LLM</strong> 上比同类策略更好保住结构，<strong>WikiText 困惑度最多降 20%</strong>。</li><li>洞察（对本库 <code>ai-system-architecture</code> / <code>neuroscience</code>）：<strong>跨域同构</strong>——大脑和 LLM 在&quot;<strong>局部模块 + 少量长途连接 = 高效推理</strong>&quot;上撞车。与 <code>cognee</code>/知识图谱主线呼应：<strong>网络的价值在&quot;簇内致密 + 簇间有捷径&quot;，而非均匀连接。</strong></li></ul><hr><h2 id="ai-智能体能在长期博弈竞赛里-自学-到登顶吗-arxiv-2610-12341" tabindex="-1">AI 智能体能在长期博弈竞赛里&quot;自学&quot;到登顶吗？（arXiv:2610.12341） <a class="header-anchor" href="#ai-智能体能在长期博弈竞赛里-自学-到登顶吗-arxiv-2610-12341" aria-label="Permalink to &quot;AI 智能体能在长期博弈竞赛里&quot;自学&quot;到登顶吗？（arXiv:2610.12341）&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-12.md</code> ｜ arXiv: 2610.12341</p></blockquote><ul><li>范式：把&quot;启发式学习（HL）&quot;形式化为 <strong>Adversarial Heuristic Learning（AHL）</strong>——让 AI 智能体当<strong>学习引擎</strong>，在<strong>权重固定</strong>的前提下改写<strong>可执行的博弈策略与配套软件</strong>。</li><li>基准：<strong>AAArena</strong>，含 <strong>12 款真实对抗博弈</strong> + <strong>1920 份人类程序档案</strong>，评测协议仿照<strong>真实竞赛</strong>：读懂规则 → 挑对手 → 复盘 → 迭代自己的程序，在<strong>有限对局/评估预算</strong>内拿最高排名。</li><li>结果：<strong>Opus5.5 + Claude Code 拿 6 枚金牌</strong>；<strong>剩余 6 条人类天梯无人登顶</strong>；<strong>规则描述越复杂的游戏表现越差</strong>。</li><li>机制发现：<strong>对手选择</strong>与<strong>密集反馈</strong>有助于策略改进；智能体既能从<strong>自己的对局（on-policy）<strong>也能从</strong>他人对局（off-policy）复盘</strong>中学到东西。</li><li>洞察（对本库 <code>ai-system-architecture</code> / <code>game-dev</code>）：<strong>&quot;能赢一半、另一半登不了顶&quot;</strong>——瓶颈被具体化为<strong>规则理解 / 策略实现 / 长程策略发展</strong>三处，而不是笼统的&quot;模型不够强&quot;。与 <code>dream-rsi</code>（把历史冻结成可回放树）同源：<strong>&quot;从复盘学&quot;（on/off-policy replay）是这一族方法的共同引擎。</strong></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/ai-system-architecture/index.md</code> ｜ 第35期 AI 板块</p></blockquote><p>关键词：BrickBench、乐高、物理可搭建、联合约束满足、BrickAgent；对齐泛化预测、66 个价值、激活表示、文字描述基线、价值空间、价值相似度、鲁棒性；小世界指数、SWI、注意力头功能图、core 分、bridge 分、Small-World Allocation、SWA 剪枝、流体推理、WikiText 困惑度；Adversarial Heuristic Learning、AAArena、12 款对抗博弈、1920 份人类程序、on-policy/off-policy 复盘、Opus5.5、Claude Code、6 枚金牌 关联：<code>topics/ai-system-architecture/science-daily-2026-10-11.md</code>（PASAC / 法律 CoT 反事实审计 / 认识论谦逊）、<code>topics/ai-system-architecture/echo-gap-memory-reward-inflation.md</code>（解释≠忠实、自评分误差）、<code>topics/ai-system-architecture/dream-rsi.md</code>（从历史/复盘学，递归自进化）、<code>topics/neuroscience/index.md</code>（小世界组织与智力的跨域同构）、<code>topics/game-dev/</code>（博弈智能体）</p>',21)])])}const h=t(n,[["render",i]]);export{q as __pageData,h as default};
